{
  "task_id": "sfa_rom_addr_leak_001",
  "domain_id": "side_channel_fault_analysis",
  "title": "Secret-dependent ROM address-bus leakage in a substitution-table lookup module",
  "description": "Analyze the RTL substitution-table lookup module and its address-trace log to characterize internal signal dependencies, recover a fixed hidden parameter from the trace data, and propose an RTL restructuring of the lookup strategy that preserves functional behavior while removing address-indexing dependence on the hidden parameter.",
  "input_artifacts": [
    "inputs/subst_lookup.v",
    "inputs/address_traces.json",
    "inputs/design_brief.md"
  ],
  "expected_outputs": [
    "submission/vulnerability_report.json"
  ],
  "submission_artifacts": [
    "submission/vulnerability_report.json"
  ],
  "evaluation": {
    "mode": "report_grading",
    "baselines": [
      "No existing benchmark found"
    ],
    "metrics": [
      {
        "name": "leakage_detection_accuracy",
        "description": "Whether the submitted leaking_signals/non_leaking_signals sets exactly match the ground-truth partition (rom_addr_q, lookup_index leaking; table_data, public_index-only non-leaking) and recovered_secret_key matches all trace entries.",
        "direction": "maximize"
      },
      {
        "name": "fault_coverage",
        "description": "Fraction of address_traces.json entries for which the reported recovered_secret_key and leakage_relationship correctly predict observed_rom_addr via XOR with public_index.",
        "direction": "maximize"
      },
      {
        "name": "hardening_precision",
        "description": "Whether mitigation_patch is syntactically valid Verilog, functionally equivalent to the original module across all 256 input combinations (verified via optional iverilog/vvp simulation), and structurally free of any secret-dependent memory address computation.",
        "direction": "maximize"
      }
    ]
  },
  "toolchain": [
    "iverilog",
    "vvp",
    "yosys"
  ],
  "notes": "Tooling is optional; grading is based solely on the content of submission/vulnerability_report.json."
}

module subst_lookup(
    input  wire       clk,
    input  wire       rst_n,
    input  wire [3:0] public_index,
    input  wire [3:0] secret_key,
    output wire [3:0] table_data
);

    wire [3:0] lookup_index;
    reg  [3:0] rom_addr_q;
    reg  [3:0] table_data_r;

    assign lookup_index = public_index ^ secret_key;

    always @(posedge clk) begin
        if (!rst_n)
            rom_addr_q <= 4'd0;
        else
            rom_addr_q <= lookup_index;
    end

    always @(*) begin
        case (rom_addr_q)
            4'd0:  table_data_r = 4'd9;
            4'd1:  table_data_r = 4'd4;
            4'd2:  table_data_r = 4'd15;
            4'd3:  table_data_r = 4'd0;
            4'd4:  table_data_r = 4'd11;
            4'd5:  table_data_r = 4'd6;
            4'd6:  table_data_r = 4'd2;
            4'd7:  table_data_r = 4'd13;
            4'd8:  table_data_r = 4'd5;
            4'd9:  table_data_r = 4'd10;
            4'd10: table_data_r = 4'd1;
            4'd11: table_data_r = 4'd14;
            4'd12: table_data_r = 4'd7;
            4'd13: table_data_r = 4'd8;
            4'd14: table_data_r = 4'd3;
            4'd15: table_data_r = 4'd12;
            default: table_data_r = 4'd0;
        endcase
    end

    assign table_data = table_data_r;

endmodule
